# -*- coding: utf-8 -*-
exec(open('lib7.py',encoding='utf-8').read())
c='p8';B='SQL 3B'
DB='thuexe'
def Q(tag,title,q,desc,note,db=DB,fs=22,ofs=22,ch='Ý chính'):
    o=SQLRUN(DBSETUP(db),q)
    return S2(c,B+' · '+tag,title,card(ch,P(*desc.split('<br>')))+CODE(PRETTY(q),fs),RES(OUT(o,ofs),'Kết quả chạy SQL')+(KEY(note) if note else ''))
S=[]
S.append(TITLE('TIN HỌC · SQL 3B','GROUP BY, HAVING<br>VÀ THỨ TỰ THỰC HIỆN','Gom nhóm, hàm tổng hợp theo nhóm, WHERE khác HAVING, thứ tự thực hiện, ORDER BY với bí danh, các mẫu câu hỏi HSG trên CSDL thuexe, quanly_diem, thuvien.',['GROUP BY','HAVING','WHERE ≠ HAVING','alias','thứ tự']))
S.append(goals(c,B,['Hiểu <b>GROUP BY</b>: gom dòng thành nhóm rồi tính theo nhóm.','Phân biệt <b>WHERE (lọc dòng)</b> và <b>HAVING (lọc nhóm)</b>.','Nắm <b>thứ tự thực hiện</b>: FROM → WHERE → GROUP BY → HAVING → SELECT → ORDER BY → LIMIT.','Viết đúng mẫu: <b>“với mỗi … cho biết …”</b>, <b>“các … có tổng/số lượng từ … trở lên”</b>.','Dùng <b>bí danh cột</b> trong ORDER BY.'],['GROUP BY','HAVING','Thứ tự thực hiện','Mẫu câu HSG','Tự kiểm tra']))
S.append(Q('1','Vì sao cần GROUP BY?','SELECT SUM(SoGio) AS TongGio FROM LuotThue','Không có GROUP BY, hàm tổng hợp gộp <b>cả bảng</b> thành một số.<br>Đề thường hỏi <b>“với mỗi khách…”</b>: cần một kết quả <b>cho từng khách</b>.','Muốn kết quả theo từng nhóm → <b>GROUP BY</b>.',ch='Câu hỏi theo nhóm'))
S.append(Q('1','GROUP BY: tổng giờ của từng khách','SELECT MaKT, SUM(SoGio) AS TongGio FROM LuotThue GROUP BY MaKT','<b>GROUP BY MaKT</b>: gom các dòng có cùng MaKT thành một nhóm, rồi hàm tổng hợp tính <b>trong từng nhóm</b>.<br>Mỗi nhóm cho <b>một dòng kết quả</b>.','5 khách → 5 dòng.',ch='Gom nhóm'))
S.append(S2(c,B+' · 1','Cơ chế gom nhóm: nhìn từng bước',card('Ba bước trong đầu',STEPS(['Lấy các dòng của bảng (sau WHERE).','<b>Gom</b> các dòng có cùng giá trị cột trong GROUP BY.','Với <b>mỗi nhóm</b>, tính SUM/COUNT/… và ghi một dòng.'])),T(tr('MaKT','Các SoGio trong nhóm','SUM',h=True)+tr('K001','3, 3, 4, 1','<b>11</b>')+tr('K002','2, 6, 4','<b>12</b>')+tr('K003','5, 2','<b>7</b>')+tr('K004','2, 2','<b>4</b>')+tr('K005','8','<b>8</b>'))+KEY('Kiểm tra: kết quả chạy thật ở slide trước trùng với bảng này.')))
S.append(Q('1','Đếm số lượt thuê mỗi loại phương tiện',"SELECT p.LoaiPT, COUNT(*) AS SoLuot FROM LuotThue l JOIN PhuongTien p ON l.MaPT = p.MaPT GROUP BY p.LoaiPT ORDER BY SoLuot DESC",'“Hiển thị loại phương tiện và số lượt thuê, xếp giảm dần theo SoLuot”.<br><b>ORDER BY</b> dùng được <b>bí danh</b> SoLuot.','Cột trong SELECT hoặc nằm trong <b>GROUP BY</b>, hoặc nằm trong <b>hàm tổng hợp</b>.',fs=17,ch='Nhóm + xếp hạng'))
S.append(S2(c,B+' · 1','Quy tắc vàng của SELECT khi có GROUP BY',card('Cột nào được chọn?',P('Mỗi cột trong SELECT phải thuộc một trong hai loại:','1. <b>Có trong GROUP BY</b>.','2. <b>Nằm trong hàm tổng hợp</b> (SUM, COUNT…).','Cột khác không xác định được giá trị đại diện cho nhóm → <b>sai</b> (nhiều hệ quản trị báo lỗi).')),CODE('-- ĐÚNG\nSELECT MaKT, SUM(SoGio)\nFROM LuotThue GROUP BY MaKT;\n\n-- SAI: Tram không nằm trong\n-- GROUP BY cũng không có hàm\nSELECT MaKT, Tram, SUM(SoGio)\nFROM LuotThue GROUP BY MaKT;',20)+KEY('Muốn lấy thêm cột → đưa vào <b>GROUP BY</b> hoặc bọc bằng <b>MIN/MAX</b>.')))
S.append(Q('2','HAVING: lọc nhóm','SELECT MaKT, SUM(SoGio) AS TongGio FROM LuotThue GROUP BY MaKT HAVING SUM(SoGio) >= 8','<b>HAVING</b> lọc <b>các nhóm</b> sau khi đã tính hàm tổng hợp.<br>“Khách có tổng từ 8 giờ trở lên” → điều kiện trên <b>SUM</b> → phải ở <b>HAVING</b>.','WHERE <b>không</b> dùng được hàm tổng hợp.',ch='Lọc sau khi gom'))
S.append(Q('2','Khách có từ 3 lượt thuê trở lên','SELECT MaKT, COUNT(*) AS SoLuot FROM LuotThue GROUP BY MaKT HAVING COUNT(*) >= 3','Điều kiện trên <b>số lượng</b> (COUNT) của nhóm → <b>HAVING</b>.','Đáp án chạy thật: K001 (4 lượt) và K002 (3 lượt).',ch='HAVING với COUNT'))
S.append(TB(c,B+' · 2','WHERE và HAVING',['','WHERE','HAVING'],[['<b>Lọc cái gì?</b>','từng <b>dòng</b>','từng <b>nhóm</b>'],['<b>Thời điểm</b>','<b>trước</b> GROUP BY','<b>sau</b> GROUP BY'],['<b>Dùng hàm tổng hợp?</b>','<b>không</b>','<b>có</b>'],['<b>Ví dụ</b>','<code>WHERE Tram=\'DN01\'</code>','<code>HAVING SUM(SoGio)&gt;=5</code>']],note=KEY('Điều kiện trên <b>từng lượt thuê</b> (trạm, năm, loại) → WHERE. Điều kiện trên <b>tổng, số lượng, trung bình</b> → HAVING.')))
S.append(Q('2','Kết hợp WHERE và HAVING',"SELECT MaKT, SUM(SoGio) AS TongGio FROM LuotThue WHERE Tram = 'DN01' AND NgayThue LIKE '2026%' GROUP BY MaKT HAVING SUM(SoGio) >= 6","Đề: “tổng giờ thuê tại trạm DN01 trong năm 2026, chỉ lấy khách có tổng từ 6 giờ trở lên”.<br><b>WHERE</b> lọc từng lượt (trạm, năm); <b>HAVING</b> lọc tổng.",'Lượt thuê K003 năm 2025 và tại DN02 <b>không được cộng</b> vì bị WHERE loại trước.',fs=17,ch='Hai tầng lọc'))
S.append(S2(c,B+' · 3','Thứ tự thực hiện (khác thứ tự viết)',card('Máy chạy câu lệnh theo thứ tự này',STEPS(['<b>FROM</b> (và JOIN): lấy bảng.','<b>WHERE</b>: lọc dòng.','<b>GROUP BY</b>: gom nhóm.','<b>HAVING</b>: lọc nhóm.','<b>SELECT</b>: chọn cột, tính biểu thức, đặt bí danh.','<b>ORDER BY</b>: sắp xếp.','<b>LIMIT</b>: cắt số dòng.'])),CODE('SELECT MaKT, SUM(SoGio) AS T\nFROM LuotThue\nWHERE Tram=\'DN01\'\nGROUP BY MaKT\nHAVING SUM(SoGio) >= 5\nORDER BY T DESC\nLIMIT 3;',19)+KEY('Vì <b>SELECT chạy sau WHERE và HAVING</b>, bí danh đặt ở SELECT thường <b>không dùng được trong WHERE</b>; nhưng <b>ORDER BY dùng được</b>.')))
S.append(Q('3','Xếp theo tổng giảm dần rồi lấy',"SELECT MaKT, SUM(SoGio) AS TongGio FROM LuotThue GROUP BY MaKT HAVING SUM(SoGio) >= 5 ORDER BY TongGio DESC",'Mẫu quen thuộc của đề: <b>GROUP BY → HAVING → ORDER BY … DESC</b>.','Đây là đáp án đúng của câu “tổng giờ, chỉ lấy từ 5 trở lên, xếp giảm dần”.',fs=19,ch='Mẫu chuẩn'))
S.append(Q('4','Mẫu: với mỗi lớp, số học sinh',"SELECT Lop, COUNT(*) AS SoHS FROM HocSinh GROUP BY Lop",'“Với mỗi lớp, cho biết tên lớp và số học sinh”.<br>Nhóm theo <b>Lop</b>, đếm bằng <b>COUNT(*)</b>.','Dữ liệu từ CSDL <b>quanly_diem</b>.',db='quanly_diem',ch='Với mỗi …'))
S.append(Q('4','Mẫu: lớp có từ 2 học sinh sinh năm 2008',"SELECT Lop, COUNT(*) AS SoHS FROM HocSinh WHERE NgaySinh LIKE '2008%' GROUP BY Lop HAVING COUNT(*) >= 2",'Điều kiện “sinh năm 2008” là của <b>từng học sinh</b> → WHERE; “từ 2 học sinh trở lên” là của <b>nhóm</b> → HAVING.','Chạy thật: 12A1 có 2 em (Bảo, Nam) và 12A2 có 3 em sinh năm 2008; 12A3 chỉ 1 em nên bị loại.',db='quanly_diem',fs=18,ch='WHERE + HAVING'))
S.append(Q('4','Mẫu: điểm trung bình môn Tin theo lớp (JOIN)',"SELECT h.Lop, AVG(k.Diem) AS DiemTB FROM KetQua k JOIN HocSinh h ON k.MaHS = h.MaHS WHERE k.MaMon = 'TIN' AND k.NamHoc = '2024-2025' GROUP BY h.Lop HAVING AVG(k.Diem) >= 8",'“Các lớp có điểm trung bình môn Tin năm học 2024-2025 từ 8,0 trở lên”.<br>Điểm ở KetQua, lớp ở HocSinh → <b>JOIN</b>.','Gồm cả ba tầng: JOIN, WHERE, GROUP BY + HAVING.',db='quanly_diem',fs=16,ch='Mẫu nâng cao'))
S.append(Q('4','Mẫu: sách được ít nhất 2 độc giả KHÁC NHAU mượn',"SELECT MaSach, COUNT(DISTINCT MaDG) AS SoDG FROM MuonSach GROUP BY MaSach HAVING COUNT(DISTINCT MaDG) >= 2",'“<b>khác nhau</b>” → <b>COUNT(DISTINCT MaDG)</b>; S002 được mượn 5 lần nhưng bởi mấy người? Xem kết quả.','COUNT(*) đếm lượt mượn, COUNT(DISTINCT) đếm người.',db='thuvien',fs=17,ch='Đếm khác nhau theo nhóm'))
S.append(Q('4','Mẫu: tổng số ngày mượn từ 10 trở lên',"SELECT MaDG, SUM(SoNgay) AS TongNgay FROM MuonSach GROUP BY MaDG HAVING SUM(SoNgay) >= 10 ORDER BY TongNgay DESC",'“Các độc giả có TỔNG số ngày mượn từ 10 ngày trở lên, sắp giảm dần theo TongNgay”.','Mẫu “tổng từ … trở lên” = <b>SUM … HAVING … &gt;=</b>.',db='thuvien',fs=17,ch='Tổng theo nhóm'))
S.append(SELF(c,B+' · 5','Tự kiểm tra 1: WHERE hay HAVING?','Mỗi điều kiện đặt ở WHERE hay HAVING? (a) trạm = DN01; (b) tổng giờ ≥ 6; (c) năm 2026; (d) số lượt ≥ 3.','',P('(a) <b>WHERE</b>: điều kiện của từng lượt.','(b) <b>HAVING</b>: trên SUM.','(c) <b>WHERE</b>: điều kiện của từng lượt.','(d) <b>HAVING</b>: trên COUNT.'),22))
S.append(SELF(c,B+' · 5','Tự kiểm tra 2: dự đoán kết quả','Không chạy máy, dự đoán kết quả rồi đối chiếu.',"SELECT MaKT, COUNT(*) AS n\nFROM LuotThue\nGROUP BY MaKT\nHAVING COUNT(*) >= 2\nORDER BY n DESC, MaKT;",P('Số lượt: K001 = 4; K002 = 3; K003 = 2; K004 = 2; K005 = 1 (loại).','Chạy thật:'+OUT(RESQ(DB,'SELECT MaKT, COUNT(*) AS n FROM LuotThue GROUP BY MaKT HAVING COUNT(*) >= 2 ORDER BY n DESC, MaKT'),20)),20))
S.append(SELF(c,B+' · 5','Tự kiểm tra (HSG): đúng hay sai?','(a) WHERE dùng được SUM. (b) HAVING chạy sau GROUP BY. (c) Cột trong SELECT có thể là cột bất kì khi GROUP BY. (d) ORDER BY dùng được bí danh. (e) “từ 3 trở lên” là &gt; 3.','',P('(a) <b>Sai</b>: dùng HAVING.','(b) <b>Đúng</b>.','(c) <b>Sai</b>: phải thuộc GROUP BY hoặc nằm trong hàm tổng hợp.','(d) <b>Đúng</b>.','(e) <b>Sai</b>: là <b>&gt;= 3</b>.'),20))
S+=END(c,B,['<b>GROUP BY</b> gom nhóm rồi tính theo nhóm.','<b>WHERE</b> lọc dòng (trước), <b>HAVING</b> lọc nhóm (sau, dùng được hàm tổng hợp).','Thứ tự chạy: <b>FROM → WHERE → GROUP BY → HAVING → SELECT → ORDER BY → LIMIT</b>.','Cột ở SELECT: thuộc GROUP BY hoặc nằm trong hàm tổng hợp.','“Khác nhau” → <b>COUNT(DISTINCT)</b>; “từ … trở lên” → <b>&gt;=</b>.'],[('Lọc tổng','HAVING SUM(…) &gt;= n'),('Lọc từng dòng','WHERE'),('Với mỗi …','GROUP BY'),('Xếp giảm','ORDER BY … DESC')],'Dùng SUM trong WHERE; thiếu GROUP BY; chọn cột lạ; nhầm &gt; với &gt;=.',['Có thể GROUP BY <b>nhiều cột</b>.','<b>HAVING</b> không bắt buộc đi với GROUP BY.','Bí danh dùng được ở ORDER BY.'],['<b>Window function</b> (ROW_NUMBER).','<b>ROLLUP</b>.','Tối ưu truy vấn lớn.'],
 [('Mệnh đề lọc nhóm?',),('Mệnh đề chạy trước SELECT?',),('Đếm người khác nhau theo nhóm?',),('“Từ 2 trở lên”?',),('Nơi đặt điều kiện trên SUM?',)],
 [('<b>HAVING</b>.',),('<b>WHERE, GROUP BY, HAVING</b>.',),('<b>COUNT(DISTINCT)</b>.',),('<b>&gt;= 2</b>.',),('<b>HAVING</b>.',)],
 [('Mức 1. Số lượt thuê của từng trạm.',),('Mức 1. Tổng giờ mỗi khách, xếp giảm dần.',),('Mức 2. Trạm có từ 4 lượt thuê trở lên.',),('Mức 2. Số học sinh mỗi lớp, chỉ lớp có từ 3 em.',),('Mức 3 (HSG). Loại phương tiện đã được từ 3 khách KHÁC NHAU trở lên thuê.',),('Mức 3 (HSG). Khách có tổng giờ thuê xe điện tại DN01 năm 2026 từ 6 giờ trở lên, hiển thị MaKT, TenKT, TongGio.',)],
 [(RESQ(DB,'SELECT Tram, COUNT(*) FROM LuotThue GROUP BY Tram').replace('\n',' / ')+'.',),('<code>GROUP BY MaKT ORDER BY SUM(SoGio) DESC</code>.',),('<code>GROUP BY Tram HAVING COUNT(*)&gt;=4</code>: DN01.',),('HocSinh GROUP BY Lop HAVING COUNT(*)&gt;=3.',),('JOIN, GROUP BY LoaiPT, <code>HAVING COUNT(DISTINCT MaKT)&gt;=3</code>.',),('JOIN 3 bảng, WHERE ba điều kiện, GROUP BY, HAVING SUM&gt;=6.',)],hper=2)
mkdeck('c3b.html','SQL 3B · GROUP BY, HAVING và thứ tự thực hiện',S)
